package com.mplad.fraud_detection.entity;
import java.time.LocalDateTime; import jakarta.persistence.*;
@Entity @Table(name="authority_reviews") public class AuthorityReview { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="project_id",nullable=false) private Project project; @Column(name="review_status",nullable=false) private String reviewStatus; @Column(nullable=false,length=1000) private String remark; @Column(name="required_action",length=300) private String requiredAction; @Column(name="review_date",nullable=false) private LocalDateTime reviewDate; public Long getId(){return id;} public Project getProject(){return project;} public String getReviewStatus(){return reviewStatus;} public String getRemark(){return remark;} public String getRequiredAction(){return requiredAction;} public LocalDateTime getReviewDate(){return reviewDate;} public void setProject(Project v){project=v;} public void setReviewStatus(String v){reviewStatus=v;} public void setRemark(String v){remark=v;} public void setRequiredAction(String v){requiredAction=v;} public void setReviewDate(LocalDateTime v){reviewDate=v;} }
